import {createServer} from 'vite';import fs from 'node:fs';import path from 'node:path'
const output=path.resolve(process.argv[2]??'../../outputs/crossgenre-20261026','audio-qa');fs.mkdirSync(output,{recursive:true})
const port=Number(process.argv[3]??5178)
const server=await createServer({server:{host:'127.0.0.1',port,strictPort:true},plugins:[{name:'qa-local-output',configureServer(server){server.middlewares.use('/audition/',(req,res,next)=>{if(req.method!=='GET')return next();const relative=decodeURIComponent((req.url??'').split('?')[0].slice(1))||'index.html';if(!/^(?:(?:index|bridge-review)\.html|[-a-z0-9]+\.(?:wav|json))$/.test(relative)){res.statusCode=400;res.end();return}const file=path.join(output,relative);if(!fs.existsSync(file)){res.statusCode=404;res.end();return}const size=fs.statSync(file).size;res.setHeader('Content-Type',relative.endsWith('.html')?'text/html; charset=utf-8':relative.endsWith('.wav')?'audio/wav':'application/json');res.setHeader('Content-Length',size);fs.createReadStream(file).pipe(res)});server.middlewares.use('/qa-data/',(req,res,next)=>{if(req.method!=='GET')return next();const relative=decodeURIComponent(req.url?.slice(1)??'');if(!/^(?:[-a-z0-9]+\.json|audio-src\/[-a-z0-9]+\.flac)$/.test(relative)){res.statusCode=400;res.end();return}const file=path.resolve(output,'..',relative);if(!fs.existsSync(file)){res.statusCode=404;res.end();return}res.setHeader('Content-Type',file.endsWith('.json')?'application/json':'audio/flac');fs.createReadStream(file).pipe(res)});server.middlewares.use('/qa-output/',(req,res,next)=>{if(req.method!=='POST')return next();const name=req.url?.slice(1);if(!name||!/^[-a-z0-9]+\.(json|wav)$/.test(name)){res.statusCode=400;res.end();return}let bytes=0;const chunks=[];req.on('data',c=>{bytes+=c.length;if(bytes>20*1024*1024)req.destroy();else chunks.push(c)});req.on('end',()=>{fs.writeFileSync(path.join(output,name),Buffer.concat(chunks));res.end('saved')})})}}]});await server.listen();server.printUrls()
